#!/usr/bin/env python3
"""Expansion lessons for existing ai-product domains: brings each to 5 lessons.
Existing counts: llm-apis 2 (+3), prompt-engineering 1 (+4), rag-basics 1 (+4),
agent-loops 1 (+4), evals 1 (+4), ai-coding-workflows 1 (+4) = 23 lessons."""
from cbt_builder import L

def build_expansion_aiprod():
    lessons = []
    scenarios = {}  # existing domains already have 6 scenarios each; none added

    def add(did, specs):
        lessons.extend(L(did, *sp) for sp in specs)

